import api from '../api/axios';

export const createReview = async ({ tourId, rating, commenting }) => {
  return api.post('/reviews', {
    tourId,
    rating,
    commenting
  });
};

export const getTourReviews = async (tourId) => {
  const res = await api.get(`/reviews/tour/${tourId}`);
  return res.data;
};
